head.script:
scwin.init = function() {
    pageList.setCount(10, true);
};
scwin.__isShowLogNormal = function() {
    var err = WebSquare.logger.getErrorLog();
    return !err;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 컨트롤 + 마우스 우클릭으로 로그보기를 실행한다.
    //1. Execute the sample file and execute log view with control + right mouse click.
    // verify step 1. 오류로그 없이 정상적인 로그가 보여진다.
    //1. A normal log is displayed without an error log.
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowLogNormal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
